<script setup lang="ts">
import PasswordRecoveryForm from '../components/PasswordRecoveryForm.vue'
import { ref,onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { request,APIError } from '../api/client'
import { PASSWORD_MAX_LENGTH,EXISTING_PASSWORD_MAX_LENGTH,passwordPolicyError } from '../auth/password-policy'
import { useAuthStore } from '../stores/auth'
const recovering=ref(false)
const username=ref(''),password=ref(''),confirmation=ref(''),loading=ref(false),checking=ref(true),error=ref(''),registrationOpen=ref(false),available=ref(false),router=useRouter(),auth=useAuthStore()
async function loadSetup(){checking.value=true;error.value='';try{const setup=await request<{registrationOpen:boolean}>('/auth/setup');registrationOpen.value=setup.registrationOpen;available.value=true}catch(e){available.value=false;error.value=e instanceof Error?e.message:'无法检查账号状态，请检查数据库连接'}finally{checking.value=false}}
async function submit(){if(!username.value.trim()||!password.value){error.value='请输入管理员账号和密码';return};if(registrationOpen.value){if(!/^[A-Za-z0-9][A-Za-z0-9_.-]{2,31}$/.test(username.value.trim())){error.value='账号需3–32位英文字母、数字、下划线、短横线或点';return};const passwordError=passwordPolicyError(password.value);if(passwordError){error.value=passwordError;return};if(password.value!==confirmation.value){error.value='两次输入的密码不一致';return}}
 loading.value=true;error.value='';try{if(registrationOpen.value)await auth.register(username.value.trim(),password.value,confirmation.value);else await auth.login(username.value.trim(),password.value);password.value='';confirmation.value='';await router.push('/dashboard')}catch(e){error.value=e instanceof Error?e.message:'登录或注册失败';if(e instanceof APIError&&e.code==='registration_closed'){registrationOpen.value=false;password.value='';confirmation.value=''}}finally{loading.value=false}}
onMounted(loadSetup)
</script>
<template><main class="login-page"><section class="login-intro"><span class="login-symbol" aria-hidden="true">M<span></span></span><h1>让资源找到<br>它的媒体库。</h1><p>从 PT 订阅到 115 云盘，再到 Emby 播放。<br>一条可追踪、可恢复的自动化链路。</p><div class="login-chain"><span>订阅</span><i>→</i><span>下载</span><i>→</i><span>云盘</span><i>→</i><span>播放</span></div><small>Media Tool · 媒体自动化</small></section><section class="login-form-panel"><div class="login-form"><PasswordRecoveryForm v-if="recovering" @back="recovering=false"/><template v-else><span class="account-kicker">{{registrationOpen?'首次设置':'管理员账户'}}</span><h2>{{registrationOpen?'注册管理员账号':'进入管理工作台'}}</h2><p class="muted">{{registrationOpen?'创建唯一的管理员账号。注册成功后，公开注册会自动关闭。':'使用注册时设置的账号和密码登录。'}}</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><p v-if="checking" role="status" class="field-hint">正在检查账号状态…</p>
<form @submit.prevent="submit"><label for="admin-username">管理员账号</label><el-input id="admin-username" v-model="username" autocomplete="username" autocapitalize="none" spellcheck="false" :maxlength="32" placeholder="例如 media_admin" size="large" :disabled="loading||checking"/><p v-if="registrationOpen" id="username-help" class="field-hint">3–32位英文字母、数字、_、- 或点，不区分大小写。</p><label for="admin-password">密码</label><el-input id="admin-password" v-model="password" type="password" show-password :autocomplete="registrationOpen?'new-password':'current-password'" :maxlength="registrationOpen?PASSWORD_MAX_LENGTH:EXISTING_PASSWORD_MAX_LENGTH" size="large" :disabled="loading||checking" :aria-describedby="registrationOpen?'password-help':undefined"/><p v-if="registrationOpen" id="password-help" class="field-hint">6–20个字符，支持中文、空格，不会去除密码首尾空格。</p><template v-if="registrationOpen"><label for="admin-password-confirm">确认密码</label><el-input id="admin-password-confirm" v-model="confirmation" type="password" show-password autocomplete="new-password" :maxlength="PASSWORD_MAX_LENGTH" size="large" :disabled="loading||checking"/></template><el-button native-type="submit" type="primary" size="large" :loading="loading" :disabled="checking||!available">{{registrationOpen?'注册并进入工作台':'进入工作台'}}</el-button></form><el-button v-if="!available&&!checking" class="retry-setup" @click="loadSetup">重新检查账号状态</el-button>
<el-button v-if="!registrationOpen&&available&&!checking" class="retry-setup" @click="recovering=true;password='';confirmation='';error=''">忘记密码？使用恢复码</el-button><div class="setup-hint"><strong>{{registrationOpen?'请先在可信环境完成注册':'账号与会话'}}</strong><p>{{registrationOpen?'首次注册前，不要把未初始化的管理端暴露到公网。账号和密码由你设置，不会生成默认管理员。':'密码不写入浏览器存储。退出或修改密码后，旧会话将失效；部署密钥不再用于登录。'}}</p></div></template></div></section></main></template>
<style scoped>.account-kicker{display:block;color:var(--accent);font-size:12px;font-weight:600;letter-spacing:1px;margin-bottom:10px}.login-form .field-hint{margin:7px 0 4px;line-height:1.6}.retry-setup{margin-top:12px}.login-form{padding-block:24px}</style>
